composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DATABASE_JDBC_URL: "jdbc:mariadb://{{serviceName}}-mariadb:3306/ejbca"
      DATABASE_USER: ejbca
      DATABASE_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      TLS_SETUP_ENABLED: {{env.TLS_SETUP_ENABLED}}
    depends_on:
      - {{serviceName}}-mariadb
  {{serviceName}}-mariadb:
    image: mariadb:11
    container_name: {{serviceName}}-mariadb
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: ejbca
      MYSQL_USER: ejbca
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_PASSWORD}}
    volumes:
      - {{appDataPath}}/mariadb:/var/lib/mysql
